import {
  Group,
  InstancedMesh,
  IcosahedronGeometry,
  PlaneGeometry,
  Mesh,
  MeshStandardNodeMaterial,
  AdditiveBlending,
  NormalBlending,
  Color,
  Matrix4,
  Object3D,
  MathUtils,
} from 'three/webgpu';
import {
  mix,
  uv,
  vec3,
  float,
  positionWorld,
  sin,
  mul,
  add,
  smoothstep,
  time,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group: CGroup } = ctx.THREE; // fallback if needed, not used directly

  const root = new Group();

  // ---------- Backdrop Gradient ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const bgColor0 = new Color('#0b0b10');
  const bgColor1 = new Color('#16161d');

  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = mix(
    vec3(bgColor0.r, bgColor0.g, bgColor0.b),
    vec3(bgColor1.r, bgColor1.g, bgColor1.b),
    uv().y
  );
  backdropMat.roughness = 1;
  backdropMat.metalness = 0;
  backdropMat.transparent = false;

  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- Particle Geometry ----------
  const icoGeom = new IcosahedronGeometry(0.012, 0);

  const TOTAL = 1200;
  const CORE_COUNT = 90;
  const FIELD_COUNT = TOTAL - CORE_COUNT;

  // ----- Field Particles -----
  const fieldMaterial = new MeshStandardNodeMaterial({
    color: new Color('#e8ecf2'),
    metalness: 0,
    roughness: 1,
    transparent: true,
    blending: NormalBlending,
    depthWrite: true,
  });

  // opacity based on world Z depth
  fieldMaterial.opacityNode = mix(
    float(0.9),
    float(0.15),
    smoothstep(float(-5), float(0), positionWorld().z)
  );

  const fieldMesh = new InstancedMesh(icoGeom, fieldMaterial, FIELD_COUNT);
  const dummy = new Object3D();

  // helper to generate random point inside ellipsoid centered at (0,0,-1.5)
  function randomEllipsoidPoint() {
    const u = Math.random();
    const v = Math.random();
    const theta = u * 2 * Math.PI;
    const phi = Math.acos(2 * v - 1);
    const r = Math.cbrt(Math.random()); // radius distribution

    const x = r * Math.sin(phi) * Math.cos(theta) * 3; // half-width 3
    const y = r * Math.sin(phi) * Math.sin(theta) * 2; // half-height 2
    const z = r * Math.cos(phi) * 2.5 - 1.5; // half-depth 2.5 then offset -1.5
    return { x, y, z };
  }

  for (let i = 0; i < FIELD_COUNT; i++) {
    const p = randomEllipsoidPoint();
    dummy.position.set(p.x, p.y, p.z);
    dummy.updateMatrix();
    fieldMesh.setMatrixAt(i, dummy.matrix);
  }
  root.add(fieldMesh);

  // ----- Core Particles -----
  const coreMaterial = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    metalness: 0,
    roughness: 0.5,
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
  });

  // emissive intensity pulsing 0.1 Hz between 1.5 and 1.8
  coreMaterial.emissiveIntensityNode = add(
    float(1.5),
    mul(float(0.3), sin(mul(time, float(0.2 * Math.PI))))
  );

  const coreMesh = new InstancedMesh(icoGeom, coreMaterial, CORE_COUNT);

  function randomCorePoint() {
    const phi = Math.random() * 2 * Math.PI;
    const cost = Math.random() * 2 - 1;
    const u = Math.random();
    const r = Math.cbrt(u) * 0.5; // radius 0.5
    const x = r * Math.sqrt(1 - cost * cost) * Math.cos(phi);
    const y = r * Math.sqrt(1 - cost * cost) * Math.sin(phi);
    const z = r * cost;
    return { x, y, z };
  }

  for (let i = 0; i < CORE_COUNT; i++) {
    const p = randomCorePoint();
    dummy.position.set(p.x, p.y, p.z);
    dummy.updateMatrix();
    coreMesh.setMatrixAt(i, dummy.matrix);
  }
  root.add(coreMesh);

  // ---------- Text ----------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  for (const item of textItems) {
    const opts = {
      fontSize: item.typography?.fontSize,
      color: item.role === 'hero' ? '#16161d' : '#e8ecf2',
      align: 'center',
      letterSpacingPx:
        item.role === 'caption' ? 0.08 * (item.typography?.fontSize ?? 18) : 0,
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    // Positioning according to spec
    if (item.role === 'hero') {
      txtObj.position.set(0, 0.5, 0.5);
    } else if (item.role === 'subhead') {
      txtObj.position.set(0, -0.25, 0.5);
    } else if (item.role === 'caption') {
      txtObj.position.set(0, -2.25, 0.5);
    }
    root.add(txtObj);
  }

  // ---------- Cinematic Primitives ----------
  const activePrimitives = [];
  const primitives = config.cinematicPrimitives ?? [];

  for (const prim of primitives) {
    if (ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
      const handler = ctx.primitives[prim.name](root, prim.params);
      if (handler) activePrimitives.push(handler);
    }
  }

  // ---------- Cleanup ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // dispose geometries and materials
    backdropGeom.dispose();
    backdropMat.dispose();
    icoGeom.dispose();
    fieldMaterial.dispose();
    coreMaterial.dispose();

    // dispose instanced meshes
    if (fieldMesh.geometry) fieldMesh.geometry.dispose();
    if (coreMesh.geometry) coreMesh.geometry.dispose();

    // cleanup primitives
    for (const h of activePrimitives) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }

    // kill any gsap timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  return root;
}
